export function t(key:string,params?:Record<string,string|number>,language:Language=currentLanguage){return interpolate(translations[language][key]??key,params);}
export function getCurrentLanguage():Language{return currentLanguage;}
export function localeForLanguage(language:Language=currentLanguage){return language==='it'?'it-IT':language==='fr'?'fr-FR':language==='es'?'es-ES':'en-US';}
export function syncStatusLabel(status:'pending'|'syncing'|'ok'|'error'|'disconnected',language:Language=currentLanguage){const key=status;return t(key,undefined,language);}
export function accessRoleLabel(role:string,language:Language=currentLanguage){return t(role,undefined,language);}
export function syncStageLabel(stage:string,language:Language=currentLanguage){return t(stage,undefined,language);}
export function widgetStrings(language:Language=currentLanguage){
  const dayNames=language==='it'?['Lun','Mar','Mer','Gio','Ven','Sab','Dom']:language==='fr'?['Lun','Mar','Mer','Jeu','Ven','Sam','Dim']:language==='es'?['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  const months=language==='it'?['gennaio','febbraio','marzo','aprile','maggio','giugno','luglio','agosto','settembre','ottobre','novembre','dicembre']:language==='fr'?['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre']:language==='es'?['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']:['January','February','March','April','May','June','July','August','September','October','November','December'];
  const addShort=language==='it'?'Nuovo':language==='fr'?'Ajout':language==='es'?'Nuevo':'New'; const completeShort=language==='it'?'Fatto':language==='fr'?'Fait':language==='es'?'Hecho':'Done'; const olderWeeks=language==='it'?'Settimane precedenti':language==='fr'?'Semaines précédentes':language==='es'?'Semanas anteriores':'Previous weeks'; const newerWeeks=language==='it'?'Settimane successive':language==='fr'?'Semaines suivantes':language==='es'?'Semanas siguientes':'Next weeks'; const activityWord=language==='it'?'attività':language==='fr'?'activités':language==='es'?'actividades':'activities'; const more=language==='it'?'altre':language==='fr'?'autres':language==='es'?'más':'more'; return {today:t('Oggi',undefined,language),calendar:t('Calendario',undefined,language),olderWeeks,newerWeeks,noActivities:t('Nessuna attività per oggi',undefined,language),allDay:t('Tutto il giorno',undefined,language),event:t('Evento',undefined,language),task:t('Task',undefined,language),addShort,completeShort,sync:t('Sincronizza con Google',undefined,language),voice:t('Comando vocale',undefined,language),activityWord,more,dayNames,months};
}
export async function getLanguage():Promise<Language>{try{const value=await AsyncStorage.getItem(LANGUAGE_KEY);if(value==='it'||value==='en'||value==='fr'||value==='es')currentLanguage=value;}catch{}return currentLanguage;}
export async function setLanguage(value:Language){currentLanguage=value;await AsyncStorage.setItem(LANGUAGE_KEY,value);}
type Ctx={language:Language;setLanguage:(value:Language)=>Promise<void>};
const LanguageContext=createContext<Ctx|null>(null);
export function LanguageProvider({children}:PropsWithChildren){
  const[language,setLanguageState]=useState<Language>('it');
  useEffect(()=>{void getLanguage().then(setLanguageState);},[]);
  const value=useMemo(()=>({language,setLanguage:async(next:Language)=>{await setLanguage(next);setLanguageState(next);}}),[language]);
  return createElement(LanguageContext.Provider,{value},children);
}
export function useLanguage(){const value=useContext(LanguageContext);if(!value)throw new Error('useLanguage must be used inside LanguageProvider');return value;}
